-- Import des courriers arrivées 2007
-- Source : 2007.xlsx (feuille 2007).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N° ARRIVEES            -> txt_numdordre (00001/jj-mm-aaaa)
--   DATE RECEPTION         -> dt_datearrivee et dt_datecourier
--   N° + DATE RECEPTION    -> txt_reference (« <N°> du jj-mm-aaaa »)
--   PRENOMS + NOMS         -> txt_prenomNom et txt_expediteur
--   objet                  -> txt_objet (libellé d'origine)
--   objet                  -> txt_designation (liste designationsParCategorie)
--   designation retenue    -> txt_categorie
--   N° TF                  -> txt_numTitreFoncier
--   N° LOT                 -> txt_numLot
--   AGENTS TRAITEURS       -> txt_agenttraiteur
--   OBSERVATIONS           -> txt_observation
--   NICAD cité dans l'objet -> txt_NICAD
-- La colonne CATEGORIES du classeur est uniforme et n'est pas reprise.
-- Un même N° répété reçoit le suffixe -2, -3…
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Référence absente : « <N°> du jj-mm-aaaa », comme le formulaire.
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Lignes importées : 1557
--
-- Répartition des catégories :
--    1526  Demande SERVICES
--      21  Information
--       5  Réclamation - Signalement
--       3  Convocation - Invitation
--       2  Réquisition - Instruction
-- Désignations :
--     885  Morcellements
--     216  Demande de Cession définitive
--     167  Demande de Régularisation par voie de Bail
--      77  Demande de terrain/Echange
--      49  Demande de délimitation
--      27  Litiges
--      25  Duplication de CIC
--      20  Réquisition d'immatriculation
--      19  Autorisation de lotir
--      10  Demande d'extraits de plan
--       8  Demande d'états des lieux
--       7  Demande d'évaluation
--       7  Tribunal
--       6  Réceptions de lotissements
--       5  Note de service
--       5  Plainte
--       4  Rapport
--       4  Autres
--       3  Décision - Arrêté
--       3  Document administratif
--       2  Formation
--       2  Instruction à suivre
--       2  Autorisation de construction
--       1  Texte juridique
--       1  Réunion
--       1  Demande de Titre foncier
--       1  Circulaire

SET NAMES utf8mb4;

START TRANSACTION;





COMMIT;
